draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // draw doubt lines
  ctx.lineWidth = 2;
  ctx.setLineDash([5, 5]);
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2);
  ctx.lineTo(W/2 + 30, H/2);
  ctx.stroke();
  ctx.setLineDash([]);

  // animate doubt lines
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2 - 30 + 10*Math.sin(t), H/2 + 10*Math.cos(t));
  ctx.lineTo(W/2 + 30 + 10*Math.sin(t), H/2 + 10*Math.cos(t));
  ctx.stroke();

  // draw question marks
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('?', W/2 - 40 + 10*Math.sin(t), H/2 + 10*Math.cos(t));
  ctx.fillText('?', W/2 + 40 + 10*Math.sin(t), H/2 + 10*Math.cos(t));

  ctx.restore();
}
